{
  "justification": "Salience is concentrated on care for wellbeing (NHS, education, housing, pensions) and group security/order (immigration, crime, defence), so Care, Loyalty, and Authority dominate; economic fairness themes are present but secondary, with Sanctity concerns smaller. Because the survey records issues not direction, weights reflect prominence regardless of stance (e.g., immigration could invoke compassion or protection).",
  "foundations": [
    {
      "foundation": "care",
      "basis": "NHS/Hospitals/Healthcare; Education/Schools; Housing; Pensions/Social security; Animal welfare",
      "weight": 0.30
    },
    {
      "foundation": "loyalty",
      "basis": "Race relations/Immigration/Immigrants; Defence/Foreign affairs/International terrorism; Common Market/EU/Europe",
      "weight": 0.20
    },
    {
      "foundation": "authority",
      "basis": "Crime/Law and order/Violence/Vandalism; Morality/Individual behaviour; Local government/Council tax",
      "weight": 0.18
    },
    {
      "foundation": "equality",
      "basis": "Poverty/Inequality; Low pay/Minimum wage/Fair wages; Housing; NHS/Hospitals/Healthcare",
      "weight": 0.16
    },
    {
      "foundation": "proportionality",
      "basis": "Economy/Economic situation; Taxation; Unemployment/Lack of industry; Inflation/Prices",
      "weight": 0.10
    },
    {
      "foundation": "sanctity",
      "basis": "Morality/Individual behaviour; Drug abuse; Pollution/Environment; Genetically Modified Foods; Nuclear weapons/Disarmament",
      "weight": 0.06
    }
  ]
}
